CREATE TABLE lending_import_batches(id TEXT PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('loan','repayment')),request_key TEXT NOT NULL UNIQUE,rows_json TEXT NOT NULL CHECK(json_valid(rows_json) AND json_type(rows_json)='array'),created_by TEXT NOT NULL REFERENCES "user"(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE lending_import_refs(kind TEXT NOT NULL CHECK(kind IN ('loan','repayment')),source_ref TEXT NOT NULL,record_id TEXT NOT NULL,batch_id TEXT NOT NULL REFERENCES lending_import_batches(id),PRIMARY KEY(kind,source_ref),UNIQUE(kind,record_id));
CREATE TRIGGER lending_import_validate BEFORE INSERT ON lending_import_batches BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM app_user_roles WHERE user_id=NEW.created_by AND role='admin') THEN RAISE(ABORT,'unauthorized') END;
 SELECT CASE WHEN json_array_length(NEW.rows_json) NOT BETWEEN 1 AND 100 THEN RAISE(ABORT,'invalid batch') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r WHERE json_type(r.value,'$.id') IS NOT 'text' OR length(json_extract(r.value,'$.id')) NOT BETWEEN 1 AND 128 OR json_type(r.value,'$.sourceRef') IS NOT 'text' OR length(trim(json_extract(r.value,'$.sourceRef'))) NOT BETWEEN 1 AND 200) THEN RAISE(ABORT,'invalid reference') END;
 SELECT CASE WHEN NEW.kind='loan' AND EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r WHERE json_type(r.value,'$.principalMinor') IS NOT 'text' OR json_extract(r.value,'$.principalMinor') GLOB '*[^0-9]*' OR length(json_extract(r.value,'$.principalMinor')) NOT BETWEEN 1 AND 16 OR CAST(json_extract(r.value,'$.principalMinor') AS INTEGER) NOT BETWEEN 1 AND 9007199254740991 OR CAST(CAST(json_extract(r.value,'$.principalMinor') AS INTEGER) AS TEXT) IS NOT json_extract(r.value,'$.principalMinor') OR json_extract(r.value,'$.currency') NOT GLOB '[A-Z][A-Z][A-Z]' OR length(json_extract(r.value,'$.currency'))<>3 OR date(json_extract(r.value,'$.disbursementDate'),'+0 days') IS NOT json_extract(r.value,'$.disbursementDate') OR (json_extract(r.value,'$.maturityDate') IS NOT NULL AND (date(json_extract(r.value,'$.maturityDate'),'+0 days') IS NOT json_extract(r.value,'$.maturityDate') OR json_extract(r.value,'$.maturityDate')<json_extract(r.value,'$.disbursementDate'))) OR length(trim(json_extract(r.value,'$.terms'))) NOT BETWEEN 1 AND 4000) THEN RAISE(ABORT,'invalid loan') END;
 SELECT CASE WHEN NEW.kind='repayment' AND EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r WHERE json_type(r.value,'$.amountMinor') IS NOT 'text' OR json_extract(r.value,'$.amountMinor') GLOB '*[^0-9]*' OR length(json_extract(r.value,'$.amountMinor')) NOT BETWEEN 1 AND 16 OR CAST(json_extract(r.value,'$.amountMinor') AS INTEGER) NOT BETWEEN 1 AND 9007199254740991 OR CAST(CAST(json_extract(r.value,'$.amountMinor') AS INTEGER) AS TEXT) IS NOT json_extract(r.value,'$.amountMinor') OR date(json_extract(r.value,'$.paymentDate'),'+0 days') IS NOT json_extract(r.value,'$.paymentDate') OR json_extract(r.value,'$.paymentDate')<json_extract(r.value,'$.disbursementDate')) THEN RAISE(ABORT,'invalid repayment') END;
 SELECT CASE WHEN NEW.kind='loan' AND EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r WHERE substr(json_extract(r.value,'$.sourceRef'),1,3)='id:') THEN RAISE(ABORT,'reserved source reference') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r GROUP BY json_extract(r.value,'$.sourceRef') HAVING count(*)>1) OR EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r JOIN lending_import_refs x ON x.kind=NEW.kind AND x.source_ref=json_extract(r.value,'$.sourceRef')) THEN RAISE(ABORT,'source reference conflict') END;
 SELECT CASE WHEN NEW.kind='loan' AND EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r WHERE NOT EXISTS(SELECT 1 FROM members m WHERE m.id=json_extract(r.value,'$.memberId') AND m.member_number=json_extract(r.value,'$.memberNumber') AND m.full_name=json_extract(r.value,'$.memberName') AND m.status='active')) THEN RAISE(ABORT,'member changed or unavailable') END;
 SELECT CASE WHEN NEW.kind='repayment' AND EXISTS(SELECT 1 FROM json_each(NEW.rows_json) r WHERE NOT EXISTS(SELECT 1 FROM loans l JOIN members m ON m.id=l.member_id WHERE (json_extract(r.value,'$.loanSourceRef')='id:'||l.id OR EXISTS(SELECT 1 FROM lending_import_refs x WHERE x.kind='loan' AND x.record_id=l.id AND x.source_ref=json_extract(r.value,'$.loanSourceRef'))) AND l.id=json_extract(r.value,'$.loanId') AND l.member_id=json_extract(r.value,'$.memberId') AND m.member_number=json_extract(r.value,'$.memberNumber') AND m.full_name=json_extract(r.value,'$.memberName') AND m.status='active' AND l.currency=json_extract(r.value,'$.currency') AND CAST(l.principal_minor AS TEXT)=json_extract(r.value,'$.principalMinor') AND l.disbursement_date=json_extract(r.value,'$.disbursementDate') AND l.maturity_date IS json_extract(r.value,'$.maturityDate') AND l.terms=json_extract(r.value,'$.terms') AND NOT EXISTS(SELECT 1 FROM loan_source_voids v WHERE v.source_kind='loan' AND v.source_id=l.id))) THEN RAISE(ABORT,'loan changed or unavailable') END;
END;
CREATE TRIGGER lending_import_apply AFTER INSERT ON lending_import_batches BEGIN
 INSERT INTO loans(id,member_id,principal_minor,currency,disbursement_date,maturity_date,terms,reference,created_by) SELECT json_extract(r.value,'$.id'),json_extract(r.value,'$.memberId'),CAST(json_extract(r.value,'$.principalMinor') AS INTEGER),json_extract(r.value,'$.currency'),json_extract(r.value,'$.disbursementDate'),json_extract(r.value,'$.maturityDate'),json_extract(r.value,'$.terms'),json_extract(r.value,'$.sourceRef'),NEW.created_by FROM json_each(NEW.rows_json) r WHERE NEW.kind='loan';
 INSERT INTO loan_repayments(id,loan_id,payment_date,amount_minor,reference,notes,created_by) SELECT json_extract(r.value,'$.id'),json_extract(r.value,'$.loanId'),json_extract(r.value,'$.paymentDate'),CAST(json_extract(r.value,'$.amountMinor') AS INTEGER),json_extract(r.value,'$.reference'),json_extract(r.value,'$.notes'),NEW.created_by FROM json_each(NEW.rows_json) r WHERE NEW.kind='repayment';
 INSERT INTO lending_import_refs(kind,source_ref,record_id,batch_id) SELECT NEW.kind,json_extract(r.value,'$.sourceRef'),json_extract(r.value,'$.id'),NEW.id FROM json_each(NEW.rows_json) r;
END;
CREATE TRIGGER lending_import_no_update BEFORE UPDATE ON lending_import_batches BEGIN SELECT RAISE(ABORT,'import history immutable'); END;
CREATE TRIGGER lending_import_no_delete BEFORE DELETE ON lending_import_batches BEGIN SELECT RAISE(ABORT,'import history immutable'); END;
CREATE TRIGGER lending_refs_no_update BEFORE UPDATE ON lending_import_refs BEGIN SELECT RAISE(ABORT,'import references immutable'); END;
CREATE TRIGGER lending_refs_no_delete BEFORE DELETE ON lending_import_refs BEGIN SELECT RAISE(ABORT,'import references immutable'); END;
